import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;

public class Main {
  public static void main(String[] args) throws Exception {
      Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/mibase", "user", "pass");

      Statement stmt = conn.createStatement();
      String sql = "DROP TABLE IF EXISTS clientes";

      // No se requiere 'commit()' para sentencias DDL (Data Definition Language) en MySQL
      stmt.executeUpdate(sql);
      System.out.println("La tabla fue destruida.");
  }
}
